package cn.course.community;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:review-workbench;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","app.seed=true","app.seed-password=TestOnly!2026Long"}) @AutoConfigureMockMvc @Transactional
class ReviewWorkbenchTest {
 @Autowired CommunityService domain;@Autowired ReviewWorkbench w;@Autowired Store s;@Autowired MockMvc mvc;
 long uid(String name){return s.uid(name+"@example.test");}void fails(int status,Runnable r){assertEquals(status,assertThrows(ApiError.Failure.class,r::run).status);}long n(Map<?,?>m,String k){return ((Number)m.get(k)).longValue();}
 Map<String,Object> list(){return list("",0,0,"ALL","ALL","ALL","ALL","oldest",1);}Map<String,Object> list(String q,long aid,long author,String state,String drafts,String evidence,String versions,String sort,int page){return w.list(1,uid("teacher"),q,aid,author,state,drafts,evidence,versions,sort,page);}
 List<Map<String,Object>> rows(Map<String,Object> packet){return (List<Map<String,Object>>)packet.get("items");}Map<String,Object> summary(Map<String,Object> packet){return (Map<String,Object>)packet.get("summary");}
 long version(int no,String title){return s.insert("INSERT INTO submission(entry_id,version_no,title,content_json,content_hash,rubric_version,idempotency_key,created_at) SELECT 1,?,?,content_json,content_hash,rubric_version,?,? FROM submission WHERE id=1",no,title,"review-version-"+no,"2030-01-01T00:00:00Z");}
 void draft(long sid,long teacher,int base){s.db.update("INSERT INTO review_draft(submission_id,teacher_id,details_json,summary,gate_reason,base_evaluation_revision,revision,updated_at) VALUES(?,?,'[]','评分私密内容，不得出现在队列','私密理由',?,1,?)",sid,teacher,base,Store.now());}
 void assistant(){s.db.update("INSERT INTO course_member(course_id,user_id,role) VALUES(1,?,'ASSISTANT')",uid("outsider"));}
 void evidence(long sid,String state){s.db.update("INSERT INTO evidence(submission_id,paragraph_id,source_title,source_url,excerpt,claim_text,state) VALUES(?,'p-gap','本地证据','https://example.test/material','摘录','论断',?)",sid,state);}
 void grade(long sid,int score){s.db.update("INSERT INTO evaluation(submission_id,teacher_id,revision_no,details_json,dimensions_json,q_raw,q_final,gate_reason,summary,active,created_at) VALUES(?,?,1,'[]','{}',?,?,'','正式评价',TRUE,?)",sid,uid("teacher"),score,score,Store.now());}
 @Test void anonymousStudentAndOtherCourseDenied()throws Exception{for(String suffix:List.of("","/dashboard","/next")){String path="/api/courses/1/review-workbench"+suffix;mvc.perform(get(path)).andExpect(status().isUnauthorized());mvc.perform(get(path).with(user("student@example.test"))).andExpect(status().isForbidden());mvc.perform(get(path).with(user("outsider@example.test"))).andExpect(status().isForbidden());}}
 @Test void readEndpointsNoStore()throws Exception{for(String suffix:List.of("","/dashboard","/next"))mvc.perform(get("/api/courses/1/review-workbench"+suffix).with(user("teacher@example.test"))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));}
 @Test void summaryCountsActualVersionsNotStudents(){version(2,"第二版");var r=list();assertEquals(3,n(summary(r),"submission_count"));assertEquals(2,n(summary(r),"pending_count"));assertEquals(1,n(summary(r),"graded_count"));}
 @Test void pendingAndGradeFilterIncludeActualZero(){grade(2,0);var r=list("",0,0,"GRADED","ALL","ALL","ALL","oldest",1);assertEquals(2,n(r,"total"));assertTrue(rows(r).stream().anyMatch(x->((Number)x.get("q_final")).doubleValue()==0));assertEquals(0,n(list("",0,0,"PENDING","ALL","ALL","ALL","oldest",1),"total"));}
 @Test void summaryIndependentOfStateDraftAndEvidence(){draft(2,uid("teacher"),0);evidence(2,"DISPUTED");var r=list("",0,0,"PENDING","MINE","DISPUTED","ALL","oldest",1);assertEquals(1,n(r,"total"));assertEquals(2,n(summary(r),"submission_count"));assertEquals(1,n(summary(r),"my_draft_count"));assertEquals(1,n(summary(r),"disputed_evidence_count"));}
 @Test void exactAssignmentAndAuthorScope(){assertEquals(1,n(list("",1,uid("peer"),"ALL","ALL","ALL","ALL","oldest",1),"total"));assertEquals(0,n(list("",999,0,"ALL","ALL","ALL","ALL","oldest",1),"total"));assertEquals(0,n(list("",0,999,"ALL","ALL","ALL","ALL","oldest",1),"total"));}
 @Test void searchIncludesFrozenTitleAssignmentAndDisplayName(){s.db.update("UPDATE entry SET title='不该用于搜索的草稿标题' WHERE id=1");assertEquals(1,n(list("光反应之后",0,0,"ALL","ALL","ALL","ALL","oldest",1),"total"));assertEquals(0,n(list("不该用于搜索",0,0,"ALL","ALL","ALL","ALL","oldest",1),"total"));assertEquals(1,n(list("林同学",0,0,"ALL","ALL","ALL","ALL","oldest",1),"total"));s.db.update("UPDATE assignment SET title='TEST special' WHERE id=1");assertEquals(2,n(list("test",0,0,"ALL","ALL","ALL","ALL","oldest",1),"total"));}
 @Test void percentUnderscoreAndBangAreLiteral(){version(2,"100%_!真实标题");assertEquals(1,n(list("%_!",0,0,"ALL","ALL","ALL","ALL","oldest",1),"total"));assertEquals(0,n(list("' OR 1=1 --",0,0,"ALL","ALL","ALL","ALL","oldest",1),"total"));}
 @Test void allPagesStableTiesNoDuplicates(){for(int i=2;i<=26;i++)version(i,"分页 "+i);var a=list("",0,0,"ALL","ALL","ALL","ALL","recent",1);var b=list("",0,0,"ALL","ALL","ALL","ALL","recent",2);assertEquals(27,n(a,"total"));assertEquals(20,rows(a).size());assertEquals(7,rows(b).size());var ids=new HashSet<>();for(var row:rows(a))assertTrue(ids.add(row.get("id")));for(var row:rows(b))assertTrue(ids.add(row.get("id")));assertEquals(rows(a),rows(list("",0,0,"ALL","ALL","ALL","ALL","recent",1)));}
 @Test void obsoletePageClampsToLastPage(){var r=list("",0,0,"ALL","ALL","ALL","ALL","oldest",999);assertEquals(1,n(r,"page"));assertEquals(2,rows(r).size());}
 @Test void newestOldestAndEvidenceSort(){long id=version(2,"最近版");s.db.update("UPDATE submission SET created_at='2000-01-01T00:00:00Z' WHERE id=2");assertEquals(2,n(rows(list()).getFirst(),"id"));assertEquals(id,n(rows(list("",0,0,"ALL","ALL","ALL","ALL","recent",1)).getFirst(),"id"));evidence(2,"DISPUTED");assertEquals(2,n(rows(list("",0,0,"ALL","ALL","ALL","ALL","evidence",1)).getFirst(),"id"));}
 @Test void latestVersionScopeDoesNotDeleteHistoricalPending(){version(2,"后续未评");version(3,"最新未评");var r=list("",0,0,"PENDING","ALL","ALL","LATEST","oldest",1);assertEquals(2,n(summary(r),"submission_count"));assertEquals(2,n(r,"total"));assertEquals(3,n(list("",0,0,"PENDING","ALL","ALL","ALL","oldest",1),"total"));assertTrue(rows(r).stream().allMatch(x->Boolean.TRUE.equals(x.get("is_latest"))));}
 @Test void draftFlagOnlyOwnerNoPrivateContent(){draft(2,uid("teacher"),0);String text=list().toString();assertFalse(text.contains("评分私密内容"));assertFalse(text.contains("私密理由"));assertFalse(text.contains("details_json"));assertEquals(1,n(list("",0,0,"ALL","MINE","ALL","ALL","oldest",1),"total"));assertEquals(1,n(list("",0,0,"ALL","NONE","ALL","ALL","oldest",1),"total"));}
 @Test void otherTeacherDraftNotVisible(){draft(2,uid("peer"),0);assertEquals(0,n(summary(list()),"my_draft_count"));assertTrue(rows(list()).stream().allMatch(x->x.get("review_draft_updated_at")==null));}
 @Test void staleDraftAfterNewEvaluation(){draft(2,uid("teacher"),0);grade(2,81);assertTrue((Boolean)rows(list("",0,uid("peer"),"ALL","MINE","ALL","ALL","oldest",1)).getFirst().get("draft_stale"));}
 @Test void assistantNeverSeesFormerOwnTeacherDraft(){assistant();draft(2,uid("outsider"),0);var r=w.list(1,uid("outsider"),"",0,0,"ALL","ALL","ALL","ALL","oldest",1);assertEquals(0,n(summary(r),"my_draft_count"));assertTrue(rows(r).stream().allMatch(x->x.get("review_draft_updated_at")==null));fails(403,()->w.list(1,uid("outsider"),"",0,0,"ALL","MINE","ALL","ALL","oldest",1));assertEquals(2,n(summary(w.dashboard(1,uid("outsider"))),"submission_count"));}
 @Test void evidenceCountsArePerVersionAndFiltersDistinct(){evidence(2,"PENDING");evidence(2,"PENDING");evidence(2,"DISPUTED");var r=list("",0,0,"ALL","ALL","PENDING","ALL","oldest",1);assertEquals(1,n(r,"total"));assertEquals(2,n(rows(r).getFirst(),"pending_evidence"));assertEquals(1,n(summary(r),"pending_evidence_count"));assertEquals(1,n(list("",0,0,"ALL","ALL","DISPUTED","ALL","oldest",1),"total"));}
 @Test void removedAuthorsRetainHistoricalRecords(){s.db.update("DELETE FROM course_member WHERE course_id=1 AND user_id=?",uid("peer"));var r=list();assertEquals(2,n(r,"total"));assertTrue(((List<Map<String,Object>>)r.get("authors")).stream().anyMatch(x->n(x,"id")==uid("peer")&&Boolean.FALSE.equals(x.get("current_member"))));fails(403,()->w.list(1,uid("peer"),"",0,0,"ALL","ALL","ALL","ALL","oldest",1));}
 // 首页与批改中心同口径只统计每篇作品的最新版本（17ec09b），旧版本不再重复计入待评审。
 @Test void dashboardCountsOnlyLatestVersions(){for(int i=2;i<=26;i++)version(i,"首页 "+i);var d=w.dashboard(1,uid("teacher"));assertEquals(2,rows(d).size());assertEquals(2,n(summary(d),"submission_count"));assertEquals(2,n(summary(d),"pending_count"));assertTrue(rows(d).stream().allMatch(x->Boolean.TRUE.equals(x.get("is_latest"))));assertTrue(rows(d).stream().anyMatch(x->n(x,"version_no")==26));assertNull(rows(d).getFirst().get("q_final"));}
 @Test void nextSkipsCurrentAndGradedAndUsesLiveState(){long id=version(2,"下一份");assertEquals(id,n((Map<?,?>)w.next(1,uid("teacher"),"",0,0,"ALL","ALL","ALL","oldest",2).get("item"),"id"));grade(id,80);assertNull(w.next(1,uid("teacher"),"",0,0,"ALL","ALL","ALL","oldest",2).get("item"));assertEquals(0,n(w.next(1,uid("teacher"),"",0,0,"ALL","ALL","ALL","oldest",2),"remaining"));}
 @Test void nextRespectsCurrentScopeAndSort(){long id=version(2,"专属待评");evidence(id,"DISPUTED");draft(id,uid("teacher"),0);var r=w.next(1,uid("teacher"),"专属",1,uid("student"),"MINE","DISPUTED","LATEST","recent",1);assertEquals(id,n((Map<?,?>)r.get("item"),"id"));assertNull(w.next(1,uid("teacher"),"不存在",0,0,"ALL","ALL","ALL","oldest",1).get("item"));}
 @Test void nextDoesNotWriteOrClaim(){long before=s.db.queryForObject("SELECT COUNT(*) FROM audit_log",Long.class);var a=w.next(1,uid("teacher"),"",0,0,"ALL","ALL","ALL","oldest",1);var b=w.next(1,uid("teacher"),"",0,0,"ALL","ALL","ALL","oldest",1);assertEquals(a,b);assertEquals(before,s.db.queryForObject("SELECT COUNT(*) FROM audit_log",Long.class));assertNull(s.one("SELECT q_final FROM submission v LEFT JOIN evaluation g ON g.submission_id=v.id AND g.active=TRUE WHERE v.id=2").get("q_final"));}
 @Test void unknownNextSubmissionRejected(){fails(404,()->w.next(1,uid("teacher"),"",0,0,"ALL","ALL","ALL","oldest",99999));fails(400,()->w.next(1,uid("teacher"),"",0,0,"ALL","ALL","ALL","oldest",-1));}
 @Test void invalidQueryFieldsRejected(){fails(400,()->list("x".repeat(81),0,0,"ALL","ALL","ALL","ALL","oldest",1));fails(400,()->list("",-1,0,"ALL","ALL","ALL","ALL","oldest",1));fails(400,()->list("",0,-1,"ALL","ALL","ALL","ALL","oldest",1));fails(400,()->list("",0,0,"bad","ALL","ALL","ALL","oldest",1));fails(400,()->list("",0,0,"ALL","bad","ALL","ALL","oldest",1));fails(400,()->list("",0,0,"ALL","ALL","bad","ALL","oldest",1));fails(400,()->list("",0,0,"ALL","ALL","ALL","bad","oldest",1));fails(400,()->list("",0,0,"ALL","ALL","ALL","ALL","bad",1));fails(400,()->list("",0,0,"ALL","ALL","ALL","ALL","oldest",0));fails(400,()->list("",0,0,"ALL","ALL","ALL","ALL","oldest",100001));}
 @Test void legacyEndpointStillReturnsList()throws Exception{mvc.perform(get("/api/courses/1/review-queue").with(user("teacher@example.test"))).andExpect(status().isOk()).andExpect(jsonPath("$[0].id").exists());}
 @Test void legacyAssistantCannotSeeFormerPrivateDraftMetadata(){assistant();draft(2,uid("outsider"),0);assertTrue(domain.queue(1,uid("outsider")).stream().allMatch(x->x.get("review_draft_updated_at")==null));}

}
